	/**
	 * Default Constructor
	 */
    public BranchService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new BranchEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(BranchRepository.class) );
		this.validator		= applicationContext.getBean(BranchValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Branch
	 */
		public Branch createBranch( CreateBranchCommand command ) {

		Branch entity = new Branch();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setBranchId( command.getBranchId() );
            entity.setName( command.getName() );
            entity.setBranchCode( command.getBranchCode() );
            entity.setAddress( command.getAddress() );
            entity.setPhone( command.getPhone() );
            entity.setOpeningHours( command.getOpeningHours() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Branch {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateBranchCommand
	 * @return		Branch
	 */
	public Branch updateBranch( UpdateBranchCommand command ) {

		Branch entity = new Branch();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setBranchId( command.getBranchId() );
            entity.setName( command.getName() );
            entity.setBranchCode( command.getBranchCode() );
            entity.setAddress( command.getAddress() );
            entity.setPhone( command.getPhone() );
            entity.setOpeningHours( command.getOpeningHours() );
            entity.setBank( command.getBank() );
            entity.setAccounts( command.getAccounts() );
            entity.setLoanAccounts( command.getLoanAccounts() );
            entity.setAtms( command.getAtms() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Branch {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteBranchCommand
	 */
	public void delete( DeleteBranchCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getBranchId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Branch {0} ", id );

	}

	/**
	 * Method to retrieve the Branch via BranchFetchOneSummary
	 * @param 	summary BranchFetchOneSummary
	 * @return 	BranchFetchOneResponse
	 */
	public Branch getBranch( BranchFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "BranchFetchOneSummary arg cannot be null" );

		Branch entity = null;
		UUID id = summary.getBranchId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Branch using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Branchs
	 *
	 * @return 	List<Branch>
	 */
    public List<Branch> getAllBranch() {
		List<Branch> list = projector.findAll( new FindAllBranchQuery() );
		return list;
	}

	/**
	 * assign Bank on Branch
	 * @param		command AssignBankToBranchCommand
	 */
	public void assignBank( AssignBankToBranchCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignBank(command.getBranchId(), command.getAssignment());

	}

	/**
	 * unAssign Bank on Branch
	 * @param		command UnAssignBankFromBranchCommand
	 */
	public void unAssignBank( UnAssignBankFromBranchCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignBank(command.getBranchId());
	}
	

